function minCostTable(cost) {
  const n = cost.length;
  const dp = new Array(n + 1).fill(0);
  for (let i = 2; i <= n; i++) {
    dp[i] = Math.min(dp[i-1] + cost[i-1], dp[i-2] + cost[i-2]);
  }
  return dp[n];
}

function minCostOptimal(cost) {
  const n = cost.length;
  let prev2 = 0, prev1 = 0;
  for (let i = 2; i <= n; i++) {
    const curr = Math.min(prev1 + cost[i-1], prev2 + cost[i-2]);
    prev2 = prev1;
    prev1 = curr;
  }
  return prev1;
}

