function wordBreakImpl(s, wordDict) {
  const wordSet = new Set(wordDict);
  const n = s.length;
  const dp = new Array(n + 1).fill(false);
  dp[0] = true;
  for (let i = 1; i <= n; i++) {
    for (let j = 0; j < i; j++) {
      if (dp[j] && wordSet.has(s.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }
  return dp[n];
}

function wordBreakIIImpl(s, wordDict) {
  const wordSet = new Set(wordDict);
  const memo = new Map();
  function dfs(start) {
    if (start === s.length) return [''];
    if (memo.has(start)) return memo.get(start);
    const result = [];
    for (let end = start + 1; end <= s.length; end++) {
      const word = s.substring(start, end);
      if (wordSet.has(word)) {
        const rest = dfs(end);
        for (const r of rest) {
          result.push(word + (r ? ' ' + r : ''));
        }
      }
    }
    memo.set(start, result);
    return result;
  }
  return dfs(0);
}

