function uniquePaths2D(m, n) {
  const dp = Array.from({length: m}, () => new Array(n).fill(1));
  for (let r = 1; r < m; r++) {
    for (let c = 1; c < n; c++) {
      dp[r][c] = dp[r-1][c] + dp[r][c-1];
    }
  }
  return dp[m-1][n-1];
}

function uniquePathsOptimal(m, n) {
  const dp = new Array(n).fill(1);
  for (let r = 1; r < m; r++) {
    for (let c = 1; c < n; c++) {
      dp[c] += dp[c-1];
    }
  }
  return dp[n-1];
}

function uniquePathsWithObstaclesImpl(obstacleGrid) {
  const m = obstacleGrid.length, n = obstacleGrid[0].length;
  if (obstacleGrid[0][0] === 1 || obstacleGrid[m-1][n-1] === 1) return 0;
  const dp = new Array(n).fill(0);
  dp[0] = 1;
  for (let c = 0; c < n; c++) {
    if (obstacleGrid[0][c] === 1) dp[c] = 0;
    else if (c > 0) dp[c] = dp[c-1];
  }
  for (let r = 1; r < m; r++) {
    if (obstacleGrid[r][0] === 1) dp[0] = 0;
    for (let c = 1; c < n; c++) {
      if (obstacleGrid[r][c] === 1) dp[c] = 0;
      else dp[c] += dp[c-1];
    }
  }
  return dp[n-1];
}

